Proceso ContarFinesDeSemana
    Definir Mutable cantidad Como Entero <- 0;
    Definir Mutable dia Como Entero <- 0;
    Leer cantidad;
    Definir Mutable cuenta Como Entero <- 0;
    Para i <- 1 Hasta cantidad Con Paso 1 Hacer
        Leer dia;
        Si dia = 6 O dia = 7 Entonces
            cuenta <- cuenta + 1;
        FinSi
    FinPara
    Escribir cuenta;
FinProceso
